// Expo config plugin: give CocoaPods resource bundles a deployment target
// Xcode still accepts.
//
// `react_native_post_install` raises every pod target's IPHONEOS_DEPLOYMENT_TARGET
// to React Native's minimum, but it skips the resource bundle targets those pods
// create. ReachabilitySwift (pulled in by expo-updates) ships a bundle at iOS 12.0,
// and Xcode 27 refuses anything below 15.0, so the release archive fails before
// anything is compiled. This plugin adds the same raise for resource bundles to
// the generated Podfile's post_install hook.
//
// See apps/mobile/RELEASING.md.

const { withPodfile } = require('expo/config-plugins');

const PLUGIN = 'plugins/withPodResourceBundleDeploymentTarget.js';
const BEGIN = '    # >>> speak-for-me resource bundle deployment target (generated by ' + PLUGIN + ', do not edit by hand)';
const END = '    # <<< speak-for-me resource bundle deployment target';

const BLOCK = `${BEGIN}
    installer.target_installation_results.pod_target_installation_results.each do |_, result|
      result.resource_bundle_targets.each do |bundle_target|
        bundle_target.build_configurations.each do |build_config|
          current = build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] || Helpers::Constants.min_ios_version_supported
          build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] =
            [Helpers::Constants.min_ios_version_supported.to_f, current.to_f].max.to_s
        end
      end
    end
${END}`;

function fail(reason) {
  return new Error(
    `${PLUGIN}: ${reason} The Expo template for ios/Podfile has changed; ` +
      'update the plugin, otherwise the iOS archive fails on pod resource bundles.'
  );
}

/** Pure transform of ios/Podfile contents. Idempotent. */
function addResourceBundleDeploymentTarget(contents) {
  let out = contents;

  // Remove a previously generated block so an updated plugin can re-insert it.
  const start = out.indexOf(BEGIN);
  if (start !== -1) {
    const stop = out.indexOf(END, start);
    if (stop === -1) throw fail(`found the marker "${BEGIN}" without its closing marker.`);
    const after = stop + END.length;
    const trailing = out.slice(after).match(/^\n+/);
    out = out.slice(0, start) + out.slice(after + (trailing ? trailing[0].length : 0));
  }

  const call = out.indexOf('    react_native_post_install(');
  if (call === -1) throw fail('could not find the react_native_post_install call.');
  const callEnd = out.indexOf('\n    )\n', call);
  if (callEnd === -1) throw fail('could not find the end of the react_native_post_install call.');
  const insertAt = callEnd + '\n    )\n'.length;
  return out.slice(0, insertAt) + BLOCK + '\n' + out.slice(insertAt);
}

/** @type {import('expo/config-plugins').ConfigPlugin} */
function withPodResourceBundleDeploymentTarget(config) {
  return withPodfile(config, (config) => {
    config.modResults.contents = addResourceBundleDeploymentTarget(config.modResults.contents);
    return config;
  });
}

module.exports = withPodResourceBundleDeploymentTarget;
module.exports.addResourceBundleDeploymentTarget = addResourceBundleDeploymentTarget;
